import math
def interp(a,s):
    a=sorted(a)
    if not a: return None
    if s<=a[0][0]: return a[0][1]
    for p,q in zip(a,a[1:]):
        if p[0]<=s<=q[0]:
            f=(s-p[0])/max(.001,q[0]-p[0]); return p[1]+f*(q[1]-p[1])
    return a[-1][1]
def control(obs):
    h=obs['hitch_deg']; th=math.radians(-h)
    cam=obs.get('views',{}).get('camera')
    if not cam: return (2*h,-.45,-23)
    sides=[[],[]]
    for b,d in cam.get('walls',[]):
        a=math.radians(b); x=d*math.cos(a); y=d*math.sin(a)
        s=-x*math.cos(th)-y*math.sin(th); z=-x*math.sin(th)+y*math.cos(th)
        if s>.2: sides[z>0].append((s,z))
    L=3.2
    r=interp(sides[0],L); l=interp(sides[1],L)
    err=(r+l)/2 if r is not None and l is not None else 0
    hd=max(-25,min(25,math.degrees(math.atan(5.2*err/(L*L)))))
    steer=max(-34,min(34,.75*h+1.8*(h-hd)))
    return (steer,-.55,-23)

