import math
cache={}
lastprint=-10
def control(o):
 global lastprint
 t=o['t']; h=o['hitch_deg']; th=math.radians(-h); rx,ry=o['rig']['trailer_rear']; look=64 if int(t/2)%2==0 else -64
 for side in ['left_mirror','right_mirror']:
  if side in o['views']:
   v=o['views'][side]; pts=[]
   for b,d in v['walls']:
    b=math.radians(b); x=v['origin'][0]+d*math.cos(b)-rx; y=v['origin'][1]+d*math.sin(b)-ry
    s=-(x*math.cos(th)+y*math.sin(th)); lat=-x*math.sin(th)+y*math.cos(th)
    if 1<s<8 and ((side=='left_mirror' and 0<lat<7) or (side=='right_mirror' and -7<lat<0)):
     pts.append((s,lat))
   if pts: cache[side]=(t,pts)
 vals={}
 for side,(tm,pts) in cache.items():
  if t-tm<5:
   near=[(s,y) for s,y in pts if 2<s<6]
   if near:
    weights=[math.exp(-((s-4)/1.6)**2) for s,y in near]
    vals[side]=sum(y*w for (s,y),w in zip(near,weights))/sum(weights)
 if len(vals)==2: center=(vals['left_mirror']+vals['right_mirror'])/2
 elif 'left_mirror' in vals: center=vals['left_mirror']-2.65
 elif 'right_mirror' in vals: center=vals['right_mirror']+2.65
 else: center=0
 ht=max(-25,min(25,math.degrees(math.atan(7.2*center/16))))
 steer=max(-40,min(40,2.2*h-1.6*ht))
 if t-lastprint>3:
  print('TRACK',round(center,2),round(ht,1),round(h,1),vals); lastprint=t
 return steer,-0.6,look

