import math
cache=None
last=-10
rightlast=-10
def control(o):
 global cache,last,rightlast
 t=o['t']; h=o['hitch_deg']; th=math.radians(-h); rx,ry=o['rig']['trailer_rear']
 look=130 if t%5<3.5 else -90
 v=o['views'].get('direct')
 if v and o['head']['settled']:
  points=[]
  for b,d in v['walls']:
   b=math.radians(b); points.append((v['origin'][0]+d*math.cos(b),v['origin'][1]+d*math.sin(b)))
  if o['head']['gaze_deg']>120:
   pts=[]
   for x,y in points:
    x-=rx; y-=ry
    s=-x*math.cos(th)-y*math.sin(th); lat=-x*math.sin(th)+y*math.cos(th)
    if 1.5<s<5.5 and lat>0: pts.append((s,lat))
   if pts:
    weights=[math.exp(-((s-3.5)/1.5)**2) for s,y in pts]
    cache=(t,sum(y*w for (s,y),w in zip(pts,weights))/sum(weights)-3.05)
  elif o['head']['gaze_deg']<-80 and t-rightlast>3:
   print('RIGHT',[(round(x,1),round(y,1)) for x,y in points if -7<x<4]); rightlast=t
 if cache is None:
  return 12,0,130
 center=cache[1]
 ht=max(-28,min(28,math.degrees(math.atan(7.2*center/16))))
 steer=max(-42,min(42,2.2*h-1.6*ht))
 if t-last>3:
  print('TRACK',round(center,2),round(h,1)); last=t
 return steer,-0.35,look

