import math
stopped=False
last=-10
def control(o):
 global stopped,last
 h=o['hitch_deg']; clearance=99
 for name,v in o['views'].items():
  if name=='periphery': continue
  for b,d in v['walls']:
   a=math.radians(b); x=v['origin'][0]+d*math.cos(a); y=v['origin'][1]+d*math.sin(a)
   if -0.5<x<3.45 and y<0:
    dx=max(0,x-3.0,-0.9-x); dy=max(0,-y-1.15)
    clearance=min(clearance,math.hypot(dx,dy))
 if h<22 or clearance<0.4:
  if not stopped:
   stopped=True; wake('Straightening limit reached; check right-front clearance')
 if o['t']-last>1:
  print('CLEAR',round(clearance,2),'HITCH',round(h,1)); last=o['t']
 return (0 if stopped else 45,0 if stopped else -0.2,-64)

